package android.content.pm;import java.io.*;import android.content.IntentSender;
public abstract class PackageInstaller {public static final String EXTRA_SESSION_ID="session",EXTRA_STATUS="status";public static final int STATUS_FAILURE=1,STATUS_PENDING_USER_ACTION=-1,STATUS_SUCCESS=0,STATUS_FAILURE_ABORTED=2;public abstract int createSession(SessionParams p)throws IOException;public abstract Session openSession(int id)throws IOException;public abstract void abandonSession(int id);public static class SessionParams{public static final int MODE_FULL_INSTALL=1,USER_ACTION_REQUIRED=1;public SessionParams(int mode){}public void setAppPackageName(String s){}public void setSize(long s){}public void setRequireUserAction(int s){}}public abstract static class Session implements AutoCloseable {public abstract OutputStream openWrite(String name,long offset,long length)throws IOException;public void fsync(OutputStream out)throws IOException{((FileOutputStream)out).getFD().sync();}public abstract void commit(IntentSender sender);public void close(){}}}
